import React, { useState, useEffect } from 'react'
import SlideBarComponent from '../../components/SlideBar/SlideBarComponent';
import { PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import './VacationDaySharehoder.scss';
import { getTotalVacationDaysByShareholder } from '../../service/statisticsservice';

const COLORS = {
    'Cổ đông': '#9c27b0',       // Tím đậm
    'Không cổ đông': '#03a9f4'  // Xanh da trời
};

const VacationDaySharehoder = () => {
    const [data, setData] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await getTotalVacationDaysByShareholder();
                // Chuyển đổi dữ liệu từ API để hiển thị
                const chartData = response.summary.map(item => ({
                    name: item.shareholder_status === 'Shareholder' ? 'Cổ đông' :
                        item.shareholder_status === 'Non-Shareholder' ? 'Không là cổ đông' :
                            item.shareholder_status, // Để xử lý các trường hợp khác nếu có
                    value: item.total_income
                })).sort((a, b) => a.name === 'Cổ đông' ? -1 : 1); // Sắp xếp để Cổ đông luôn ở trước

                setData(chartData);
            } catch (error) {
                console.error("Error fetching income data:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    if (loading) {
        return (
            <div className='container'>
                <div className='sidebar'>
                    <SlideBarComponent />
                </div>
                <div className='content w-100 d-flex justify-content-center align-items-center'>
                    <div className="spinner-border text-primary" role="status">
                        <span className="visually-hidden">Đang tải...</span>
                    </div>
                </div>
            </div>
        );
    }
    return (
        <div className='container d-flex'>
            <div className='sidebar'>
                <SlideBarComponent />
            </div>

            <div className='content p-4 w-100'>
                <h3 className="mb-4">Thống kê Ngày Nghỉ - Trạng Thái Cổ Đông</h3>

                <div className="row">
                    <div className="col-md-6">
                        <table className="table table-bordered table-hover">
                            <thead className="table-dark">
                                <tr>
                                    <th>Trạng thái</th>
                                    <th>Số ngày nghỉ</th>
                                </tr>
                            </thead>
                            <tbody>
                                {data.map((item, index) => (
                                    <tr key={index}>
                                        <td>{item.name}</td>
                                        <td>{item.value} ngày</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>

                    <div className="col-md-6">
                        <h5 className="text-center mb-4" style={{ paddingBottom: '20px' }}>Biểu đồ Ngày Nghỉ</h5>
                        <ResponsiveContainer width="100%" height={400}>
                            <PieChart>
                                <Pie
                                    data={data}
                                    dataKey="value"
                                    nameKey="name"
                                    cx="50%"
                                    cy="50%"
                                    outerRadius={150}
                                    fill="#8884d8"
                                    label
                                >
                                    {data.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[entry.name]} />
                                    ))}
                                </Pie>
                                <Tooltip
                                    formatter={(value) => [`${value} ngày`, 'Số ngày nghỉ']}
                                    labelFormatter={(label) => `Trạng thái: ${label}`}
                                />
                                <Legend />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default VacationDaySharehoder;
